[CmdletBinding()]
param([int]$Messages = 40, [switch]$KeepDatabase)

$ErrorActionPreference = 'Stop'
$repo = (Resolve-Path (Join-Path $PSScriptRoot '..\..\..')).Path
$database = "todir_perf_worker_{0}_{1}" -f (Get-Date -Format 'yyyyMMddHHmmss'), $PID
$artifacts = Join-Path $repo 'artifacts\performance'; New-Item -ItemType Directory -Path $artifacts -Force | Out-Null
$log = Join-Path $artifacts "worker-$database.log"; $errorLog = Join-Path $artifacts "worker-$database.err.log"; $worker = $null
function Psql([string]$db,[string]$sql){$o=&docker exec todir-postgres-1 psql -U postgres -d $db -v ON_ERROR_STOP=1 -t -A -c $sql;if($LASTEXITCODE-ne 0){throw "psql failed"};($o-join"`n").Trim()}
function Snapshot { $v=Psql $database "select json_build_object('pending',(select count(*) from platform.outbox_message where tenant_id='$tenant' and status='Pending'),'published',(select count(*) from platform.outbox_message where tenant_id='$tenant' and status='Published'),'inboxProcessed',(select count(*) from platform.inbox_message where tenant_id='$tenant' and consumer_endpoint='projects-source-integration' and processed_at is not null),'costFacts',(select count(*) from business_projects.project_cost_fact where tenant_id='$tenant' and source_module='expenses' and source_type='ExpenseFinalizedV1'))";if($v){$v|ConvertFrom-Json} }
try {
    Psql postgres "create database `"$database`" template template0"|Out-Null
    $env:DOTNET_ENVIRONMENT='Development';$env:ASPNETCORE_ENVIRONMENT='Development';$env:TODIR_REPOSITORY_ROOT=$repo;$env:TODIR_MIGRATOR_CONNECTION="Host=127.0.0.1;Port=15432;Database=$database;Username=postgres;Password=postgres;Include Error Detail=true";$env:TODIR_RUNTIME_PASSWORD='todir-app-dev';$env:SEED_DEFAULT_PASSWORD='TodirDev2026!'
    &dotnet run --configuration Release --no-build --project (Join-Path $repo 'backend\DbMigrator\DbMigrator.csproj') -- --seed development;if($LASTEXITCODE-ne 0){throw 'migration/seed failed'}
    $tenant=Psql $database "select id::text from platform.tenant where slug='atlas-trading'";$entity=Psql $database "select id::text from platform.legal_entity where tenant_id='$tenant' and status='Active' order by id limit 1";$project=Psql $database "select id::text from business_projects.project where tenant_id='$tenant' and legal_entity_id='$entity' and lifecycle_state='Active' order by id limit 1";if(-not$project){throw 'seeded project missing'}
    $rows=@();$ids=@();for($i=1;$i-le$Messages;$i++){ $id=[guid]::NewGuid();$source=[guid]::NewGuid();$ids+=$id;$payload=('{"projectId":"'+$project+'","legalEntityId":"'+$entity+'","expenseId":"'+$source+'","currencyCode":"EGP","baseAmount":10}');$rows+="('$id'::uuid,'ExpenseFinalizedV1','$payload'::jsonb,'$tenant'::uuid,now(),'$id'::uuid,'$id'::uuid,'expenses','Pending',0)" }
    Psql $database ("insert into platform.outbox_message(id,message_type,payload,tenant_id,occurred_at,correlation_id,causation_id,source_module,status,attempts) values"+($rows-join',')+";")|Out-Null
    $env:TODIR_DATABASE_CONNECTION="Host=127.0.0.1;Port=15432;Database=$database;Username=erp_app;Password=todir-app-dev;Include Error Detail=true;Maximum Pool Size=32;Application Name=platform-perf-worker";$env:TODIR_RABBITMQ_HOST='127.0.0.1';$env:TODIR_RABBITMQ_PORT='5672';$env:TODIR_RABBITMQ_USER='todir';$env:TODIR_RABBITMQ_PASSWORD=if($env:TODIR_RABBITMQ_PASSWORD){$env:TODIR_RABBITMQ_PASSWORD}else{'todir-dev-only'};$env:TODIR_RABBITMQ_VHOST='/erp-dev';$env:TODIR_RABBITMQ_CONSUMER='true';$env:TODIR_FILE_LOGGING_ENABLED='false'
    $dll=Join-Path $repo 'backend\Worker\bin\Release\net10.0\Worker.dll';$sw=[Diagnostics.Stopwatch]::StartNew();$worker=Start-Process dotnet -ArgumentList @($dll) -WorkingDirectory $repo -RedirectStandardOutput $log -RedirectStandardError $errorLog -WindowStyle Hidden -PassThru
    $last=$null;for($attempt=1;$attempt-le240;$attempt++){Start-Sleep -Milliseconds 500;$last=Snapshot;if($last.costFacts-ge$Messages){break}}
    $sw.Stop();$firstCount=[int]$last.costFacts;if($firstCount-lt$Messages){throw "Worker did not apply all messages; applied $firstCount/$Messages. See $log"}
    $replayId=$ids[0];Psql $database "update platform.outbox_message set status='Pending',published_at=null,next_attempt_at=now() where id='$replayId'::uuid"|Out-Null;$before=[int](Snapshot).costFacts;for($attempt=1;$attempt-le120;$attempt++){Start-Sleep -Milliseconds 500;$last=Snapshot;if($last.inboxProcessed-ge$Messages+1){break}};$after=[int](Snapshot).costFacts
    if($after-ne$before){throw "Duplicate replay changed cost facts: before=$before after=$after"}
    $proc=Get-Process -Id $worker.Id -ErrorAction SilentlyContinue;$report=[pscustomobject]@{Commit=(&git rev-parse HEAD).Trim();Database=$database;Messages=$Messages;ElapsedSeconds=[Math]::Round($sw.Elapsed.TotalSeconds,2);ThroughputPerSecond=[Math]::Round($Messages/[Math]::Max(.001,$sw.Elapsed.TotalSeconds),2);FinalSnapshot=$last;DuplicateReplayCostFactsUnchanged=($after-eq$before);WorkerPid=$worker.Id;WorkerWorkingSetMiB=if($proc){[Math]::Round($proc.WorkingSet64/1MB,2)}else{$null};RabbitMq='local todir-rabbitmq-1';Envelope='Outbox -> RabbitMQ -> Worker -> Inbox -> PostgreSQL'};$report|ConvertTo-Json -Depth 8|Set-Content (Join-Path $artifacts "worker-performance-$database.json") -Encoding utf8;$report|ConvertTo-Json -Depth 8
} finally {if($worker-and-not$worker.HasExited){Stop-Process -Id $worker.Id -Force};if(-not$KeepDatabase){for($a=1;$a-le20;$a++){try{Psql postgres "drop database `"$database`""|Out-Null;break}catch{if($a-eq20){throw};Start-Sleep -Milliseconds 500}}}}
